from pathlib import Path
from html import escape
root=Path(__file__).parent/'dist'
nav=[('index.html','Accueil'),('a-propos.html','À propos'),('services.html','Expertises'),('conferences.html','Interventions'),('realisations.html','Projets'),('ressources.html','Ressources')]
def cta(): return '''<section class="section"><div class="wrap callout"><div><span class="eyebrow">Le prochain chapitre commence ici</span><h2>Une ambition. Un défi.<br>Parlons-en.</h2><p>Clarifions votre besoin et construisons la suite.</p></div><a class="btn" href="contact.html">Prendre contact</a></div></section>'''
def page(file,title,desc,content):
 links=''.join(f'<a href="{u}" '+('aria-current="page"' if u==file else '')+f'>{n}</a>' for u,n in nav)
 html=f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | Coach OLOU</title><meta name="description" content="{escape(desc)}"><meta name="theme-color" content="#141414"><meta property="og:title" content="{escape(title)} | Coach OLOU"><meta property="og:description" content="{escape(desc)}"><meta property="og:type" content="website"><link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' fill='%23141414'/%3E%3Ctext x='32' y='45' text-anchor='middle' font-family='Arial' font-size='42' font-weight='bold' fill='%23e5b354'%3EO%3C/text%3E%3C/svg%3E"><link rel="stylesheet" href="style.css"><script src="site.js" defer></script></head><body><a class="skip" href="#main">Aller au contenu</a><header><div class="wrap nav"><a class="brand" href="index.html" aria-label="Coach OLOU, accueil">COACH OLOU<span>.</span></a><button class="menu" aria-expanded="false" aria-controls="navigation">Menu</button><nav id="navigation" class="navlinks" aria-label="Navigation principale">{links}<a class="navcontact" href="contact.html" {'aria-current="page"' if file=='contact.html' else ''}>Parlons-en</a></nav></div></header><main id="main">{content}</main><footer><div class="wrap"><div class="footgrid"><div><a class="brand" href="index.html">COACH OLOU<span>.</span></a><p>Créateur de Valeur Ajoutée.<br>Stratégie. Transmission. Protection.</p><p>Basé à Ouagadougou.<br>Engagé en Afrique francophone.</p></div><div class="footlinks"><div><strong>Explorer</strong><a href="a-propos.html">Mon parcours</a><a href="services.html">Mes expertises</a><a href="realisations.html">Mes entreprises</a></div><div><strong>Construire ensemble</strong><a href="conferences.html">Inviter Coach OLOU</a><a href="contact.html?objet=Coaching">Être accompagné</a><a href="contact.html">Me contacter</a></div></div></div><div class="footbottom"><span>© 2026 Euloge Babatoundé OLOU</span><span>Vérité · Excellence · Transmission · Protection</span><a href="contact.html#confidentialite">Confidentialité</a></div></div></footer></body></html>'''
 html=html.replace('<meta name="theme-color" content="#141414">','<meta name="robots" content="index,follow"><meta name="theme-color" content="#141414">')
 html=html.replace('<meta property="og:type" content="website">','<meta property="og:type" content="website"><meta property="og:locale" content="fr_FR"><meta name="twitter:card" content="summary">')
 html=html.replace('<button class="menu" aria-expanded="false"','<button class="menu" type="button" aria-expanded="false"')
 html=html.replace('Votre application de messagerie s’ouvrira avec votre demande préremplie. Vous pourrez la relire et l’envoyer vous-même.','Votre message sera préparé. Vous pourrez ouvrir votre messagerie ou le copier.')
 if file == 'index.html':
  marker='<section class="section dark"><div class="wrap split"><div><span class="eyebrow gold">02 / Une conviction, un parcours</span>'
  html=html.replace(marker,proofs+marker)
 (root/file).write_text(html)
def hero(label,title,txt): return f'<section class="pagehero dark"><div class="wrap"><div class="breadcrumb"><a href="index.html">Accueil</a> / {label}</div><span class="eyebrow gold">{label}</span><h1>{title}</h1><p>{txt}</p></div></section>'
proofs='''<section class="section"><div class="wrap"><div class="sectionhead"><div><span class="eyebrow label">02 / Des preuves par l’action</span><h2>Des missions concrètes.<br>Une exigence de terrain.</h2></div><p>Quelques réalisations qui montrent comment je relie stratégie, contenu, production et transmission.</p></div><div class="twocol"><article class="project"><span class="eyebrow">Lancement & communication</span><h3>Yirmea-Immo</h3><p>Accompagnement du lancement officiel au Burkina Faso : coordination, communication, mobilisation des médias et production de contenus.</p><p class="impact"><strong>Contribution</strong><br>Relier la présentation de la solution, la rencontre avec les médias et la prise de parole de la marque.</p><a class="textlink" href="realisations.html#projects">Voir la mission</a></article><article class="project"><span class="eyebrow">Communication institutionnelle</span><h3>ARCOP Burkina Faso</h3><p>Audit digital, stratégie de communication, structuration de la présence sur les réseaux sociaux et couverture en direct.</p><p class="impact"><strong>Contribution</strong><br>Rendre l’information institutionnelle plus accessible et renforcer la présence digitale.</p><a class="textlink" href="realisations.html#projects">Voir la mission</a></article><article class="project"><span class="eyebrow">Production & diffusion</span><h3>OLOUSTREAM</h3><p>Captation multicaméra, réalisation de podcasts, diffusion d’événements et création de contenus institutionnels.</p><p class="impact"><strong>Contribution</strong><br>Prolonger la portée d’un événement et valoriser les prises de parole.</p><a class="textlink" href="realisations.html#projects">Voir l’activité</a></article><article class="project"><span class="eyebrow">Parcours & transmission</span><h3>Coaching & formation</h3><p>Accompagnement des talents et des professionnels autour de la connaissance de soi, des priorités et du projet.</p><p class="impact"><strong>Contribution</strong><br>Relier les aspirations à des actions concrètes et à un suivi des progrès.</p><a class="textlink" href="services.html#coaching">Voir l’expertise</a></article></div></div></section>'''
companies='''<div class="companygrid"><article class="company"><span class="type">Production & diffusion</span><div class="wordmark">OLOUSTREAM</div><p>Donner une forme et une audience à vos idées : production audiovisuelle, podcasts, captation et live streaming.</p><a class="textlink" href="realisations.html#entreprises">Découvrir OLOUSTREAM</a></article><article class="company"><span class="type">Stratégie & communication</span><div class="wordmark">La Gazelle<span class="gold">.</span></div><p>Clarifier votre positionnement, faire vivre votre marque et construire une présence digitale qui sert vos objectifs.</p><a class="textlink" href="realisations.html#entreprises">Découvrir La Gazelle</a></article><article class="company"><span class="type">Média & transmission</span><div class="wordmark">Wadjo TV</div><p>Mettre en lumière les parcours, les idées et les initiatives qui font avancer l’Afrique.</p><a class="textlink" href="realisations.html#entreprises">Découvrir Wadjo TV</a></article></div>'''
page('index.html','Euloge OLOU — Créateur de Valeur Ajoutée','Stratégie digitale, personal branding, coaching et e-réputation. Euloge OLOU accompagne les leaders, les talents et les organisations en Afrique.', '''<section class="hero dark"><div class="wrap"><div class="herogrid"><div class="herotext"><span class="eyebrow gold">Euloge Babatoundé OLOU · Consultant & entrepreneur</span><h1>Votre image ouvre<br>des portes.<br><em>Donnons-lui<br>de la force.</em></h1><p class="intro">J’aide les marques, les leaders et les talents à devenir visibles, crédibles et utiles. Avec une direction claire, des contenus qui comptent et une image protégée.</p><div class="buttons"><a class="btn" href="contact.html">Parlons de votre projet</a><a class="btn outline" href="services.html">Découvrir mes expertises</a></div><p class="heronote">ANCRÉ EN AFRIQUE. TOURNÉ VERS L’IMPACT.</p></div><div class="portrait"><img src="assets/euloge-olou.png" alt="Euloge OLOU, consultant et coach professionnel" fetchpriority="high" width="1145" height="1215"><div class="caption"><strong>Coach OLOU</strong><span>Créateur de Valeur Ajoutée</span></div></div></div><div class="stats"><div class="stat"><strong>17+</strong><span>années d’expérience</span></div><div class="stat"><strong>6 800</strong><span>personnes et entreprises formées</span></div><div class="stat"><strong>90</strong><span>conférences et ateliers animés</span></div><div class="stat"><strong>7 pays</strong><span>d’intervention en Afrique</span></div></div></div></section><section class="section"><div class="wrap"><div class="sectionhead"><div><span class="eyebrow label">01 / Mes expertises</span><h2>Vous avez du potentiel.<br>Faisons-en une force.</h2></div><p>Quatre expertises complémentaires pour aligner ce que vous êtes, ce que vous montrez et ce que vous construisez.</p></div><div class="grid4"><article class="expert"><span class="num">01</span><h3>Personal branding<br>& image</h3><p>Affirmer votre différence et inspirer confiance aux bonnes personnes.</p><a class="textlink" href="services.html#branding">Construire mon image</a></article><article class="expert"><span class="num">02</span><h3>Stratégie digitale<br>& communication</h3><p>Donner un cap à vos contenus et un objectif à votre présence digitale.</p><a class="textlink" href="services.html#digital">Structurer ma présence</a></article><article class="expert"><span class="num">03</span><h3>Cybersécurité<br>& e-réputation</h3><p>Prévenir les risques numériques et protéger votre capital confiance.</p><a class="textlink" href="services.html#protection">Protéger mon image</a></article><article class="expert"><span class="num">04</span><h3>Coaching<br>& reconversion</h3><p>Identifier votre talent, clarifier votre projet et passer à l’action.</p><a class="textlink" href="services.html#coaching">Activer mon potentiel</a></article></div></div></section><section class="section dark"><div class="wrap split"><div><span class="eyebrow gold">02 / Une conviction, un parcours</span><blockquote class="quote">« Un talent ne devrait pas rester invisible.<br>Une ambition mérite <span class="gold">une direction.</span> »</blockquote></div><div><p>Je suis Euloge OLOU. Entrepreneur, consultant, formateur et coach professionnel certifié. Depuis plus de 17 ans, j’évolue à la croisée du contenu, de la stratégie, de l’humain et de la sécurité.</p><p>Du Bénin au Burkina Faso, mon parcours s’est construit sur le terrain : dans les médias, auprès des entreprises et aux côtés de celles et ceux qui cherchent leur voie.</p><div class="tags"><span class="tag">Coach certifié John Maxwell</span><span class="tag">Team Builder professionnel</span></div><a class="textlink" href="a-propos.html">Découvrir mon parcours</a></div></div></section><section class="section"><div class="wrap split"><div><span class="eyebrow label">03 / Coaching & transformation</span><h2>Votre prochain chapitre<br>ne s’écrira pas tout seul.</h2><p>Jeunes en quête de direction, professionnels en reconversion : construisons une trajectoire qui vous ressemble et un plan pour avancer.</p><a class="btn" href="contact.html?objet=Coaching">Démarrer mon accompagnement</a></div><div class="timeline"><article><time>01 / COMPRENDRE</time><h3>Reconnaître votre talent</h3><p>Faire le point sur vos forces, vos aspirations et ce qui vous freine.</p></article><article><time>02 / STRUCTURER</time><h3>Choisir une direction</h3><p>Transformer une envie de changement en projet concret et réaliste.</p></article><article><time>03 / AGIR</time><h3>Passer à l’action, avec méthode</h3><p>Définir vos prochaines étapes, suivre vos progrès et ajuster votre parcours.</p></article></div></div></section><section class="section dark"><div class="wrap"><div class="sectionhead"><div><span class="eyebrow gold">04 / L’entrepreneur derrière le conseil</span><h2>Je transmets<br>ce que je pratique.</h2></div><p>Trois univers, une même ambition : créer de la valeur par le contenu, la stratégie et la transmission.</p></div>'''+companies+'''</div></section>'''+cta())
page('a-propos.html','Mon parcours','Euloge OLOU, entrepreneur béninois basé au Burkina Faso, consultant, formateur et coach professionnel certifié.',hero('À propos','Penser juste.<br>Faire utile. Transmettre.','Je suis Euloge Babatoundé OLOU. Ma conviction : une image forte se construit sur une valeur réelle, une direction claire et des actes cohérents.')+'''<section class="section"><div class="wrap split"><img class="aboutphoto" src="assets/euloge-olou.png" alt="Portrait d’Euloge OLOU" width="1145" height="1215"><div><span class="eyebrow label">Un parcours ancré dans le réel</span><h2>Du récit des autres<br>à l’activation des talents.</h2><p>Le journalisme m’a appris à écouter, à chercher le sens et à rendre une histoire compréhensible. La télévision m’a appris à produire, à coordonner et à tenir un engagement collectif.</p><p>L’entrepreneuriat a élargi cette exigence : une idée doit pouvoir prendre forme, rencontrer son public et créer de la valeur.</p><p>Aujourd’hui, je relie ces expériences pour accompagner les marques, les dirigeants et les talents. Je travaille autant sur la clarté du message que sur la cohérence du parcours et la protection de l’image.</p></div></div></section><section class="section dark"><div class="wrap split"><div><span class="eyebrow gold">Ce qui me guide</span><h2>La foi comme ancrage.<br>L’action comme réponse.</h2><p>Ma foi en Dieu nourrit mon engagement. Elle m’invite à faire fructifier ce que j’ai reçu et à transmettre ce que j’ai appris.</p></div><div><h3>Vérité</h3><p>Construire une image fidèle à la personne et à la valeur qu’elle apporte.</p><h3>Excellence</h3><p>Soigner le fond, la forme et l’exécution.</p><h3>Transmission</h3><p>Rendre les autres plus autonomes et capables d’agir.</p><h3>Protection</h3><p>Intégrer les risques humains, numériques et réputationnels dans les décisions.</p></div></div></section><section class="section"><div class="wrap split"><div><span class="eyebrow label">Quelques étapes</span><h2>Un fil conducteur :<br>faire avancer.</h2><p>Béninois, installé à Ouagadougou, j’interviens auprès d’organisations et de talents en Afrique de l’Ouest et en Afrique centrale.</p><div class="tags"><span class="tag">Communication & médias</span><span class="tag">Leadership & gouvernance</span><span class="tag">Sécurité globale</span></div></div><div class="timeline"><article><time>LE JOURNALISME</time><h3>Écouter et raconter</h3><p>Reporter, chef desk culture et chef d’éditions au quotidien béninois L’Autre Vision.</p></article><article><time>2015–2019 · CANAL3 BURKINA</time><h3>Produire et piloter</h3><p>Responsabilité des productions et des projets : équipes, contenus, dispositifs et développement de la chaîne.</p></article><article><time>DEPUIS 2019 · ENTREPRENEURIAT</time><h3>Construire un écosystème</h3><p>Développement d’OLOUSTREAM, de La Gazelle et de projets médias pour conjuguer production, stratégie et diffusion.</p></article><article><time>AUJOURD’HUI · ACCOMPAGNEMENT</time><h3>Transmettre et protéger</h3><p>Coaching professionnel, formation, cohésion d’équipe, stratégie digitale et gouvernance de la sécurité globale.</p></article></div></div></section>'''+cta())
services=[('branding','01','Personal branding & image','Votre valeur est réelle. Mais votre image la rend-elle lisible ?','Une présence dispersée ou un message trop général peut rendre votre expertise difficile à comprendre.','Nous clarifions votre positionnement, votre récit professionnel et vos messages clés, puis nous les déclinons sur vos supports.',['Diagnostic de votre image et de vos prises de parole','Positionnement, biographie et messages clés','Ligne éditoriale et contenus de personal branding'],'Une image cohérente, identifiable et alignée sur les opportunités que vous visez.'),('digital','02','Stratégie digitale & communication','Publier davantage ne suffit pas. Il faut savoir pourquoi.','Des contenus sans cap mobilisent du temps sans toujours servir les objectifs de votre organisation.','Nous définissons vos publics, vos priorités et votre stratégie de contenus, avec un dispositif éditorial et des indicateurs utiles.',['Audit de présence digitale et recommandations','Stratégie social media et calendrier éditorial','Production de contenus, campagnes et reporting'],'Une communication structurée, avec des actions et des résultats que vous pouvez suivre.'),('protection','03','Cybersécurité & e-réputation','La confiance se construit. Elle se protège aussi.','Un compte mal sécurisé, une prise de parole maladroite ou une crise mal préparée peut fragiliser votre réputation.','Nous travaillons sur la sensibilisation, les pratiques de protection des comptes, la veille et la préparation de la réponse réputationnelle.',['Sensibilisation à la cyberhygiène et aux risques numériques','Veille e-réputation et analyse des points de vulnérabilité','Préparation des messages et accompagnement de communication de crise'],'Des équipes mieux sensibilisées et une organisation mieux préparée à protéger son image.'),('coaching','04','Coaching & reconversion','Vous voulez avancer. Commençons par trouver votre direction.','Vous avez du potentiel, mais votre projet manque de clarté, de confiance ou d’un plan pour devenir concret.','Nous identifions vos forces, explorons vos options et construisons un parcours d’action adapté à votre situation.',['Activation de talents pour jeunes et professionnels','Clarification du projet et accompagnement de reconversion','Leadership, confiance et cohésion d’équipe'],'Un cap choisi, des priorités claires et des étapes concrètes pour progresser.')]
body=hero('Expertises','De la clarté.<br>De la cohérence. De l’action.','Choisissez votre point de départ. Nous construirons un accompagnement adapté à votre besoin, votre contexte et vos moyens.')+'<section class="section"><div class="wrap">'
for id,n,title,headline,problem,sol,items,result in services:
 body+=f'<article class="service" id="{id}"><div><span class="num">EXPERTISE {n}</span><h2>{title}</h2></div><div><h3>{headline}</h3><p>{problem}</p><h4>Comment je vous accompagne</h4><p>{sol}</p><ul>'+''.join(f'<li>{i}</li>' for i in items)+f'</ul><h4>Ce que nous visons</h4><p>{result}</p><a class="btn" href="contact.html?objet={id}">Discuter de mon besoin</a></div></article>'
body+='</div></section>'+cta()
page('services.html','Mes expertises','Personal branding, stratégie digitale, cybersécurité, e-réputation, coaching et reconversion professionnelle.',body)
page('conferences.html','Conférences & interventions','Invitez Coach OLOU pour une conférence, un atelier, une formation ou une intervention sur le leadership, le digital et les talents.',hero('Conférences & interventions','Des idées qui éclairent.<br>Des échanges qui font avancer.','Conférences, panels, ateliers et formations : des interventions ancrées dans vos enjeux, nourries par la pratique et orientées vers l’action.')+'''<section class="section"><div class="wrap"><div class="sectionhead"><div><span class="eyebrow label">Les sujets que je porte</span><h2>Un contenu adapté<br>à votre public.</h2></div><p>Entreprises, institutions, incubateurs, établissements de formation et communautés professionnelles.</p></div><div class="twocol"><article class="panel"><span class="num">01 / IMAGE & INFLUENCE</span><h3>Construire une image qui inspire confiance</h3><p>Personal branding, prise de parole, cohérence et réputation : faire comprendre sa valeur sans se disperser.</p><span class="small muted">Dirigeants · Entrepreneurs · Experts</span></article><article class="panel"><span class="num">02 / TALENT & TRAJECTOIRE</span><h3>Transformer son potentiel en projet</h3><p>Identifier ses forces, dépasser l’indécision et organiser le passage à l’action.</p><span class="small muted">Jeunes · Étudiants · Professionnels en transition</span></article><article class="panel"><span class="num">03 / DIGITAL & PROTECTION</span><h3>Être visible sans devenir vulnérable</h3><p>Culture numérique, cyberhygiène et e-réputation : rapprocher les enjeux de communication et de protection.</p><span class="small muted">Équipes · Institutions · Décideurs</span></article><article class="panel"><span class="num">04 / LEADERSHIP & COLLECTIF</span><h3>Faire grandir les personnes et les équipes</h3><p>Leadership, responsabilité et cohésion : donner un cap commun et favoriser l’engagement.</p><span class="small muted">Managers · Associations · Organisations</span></article></div></div></section><section class="section dark"><div class="wrap split"><div><span class="eyebrow gold">Préparer une intervention</span><h2>Votre contexte<br>donne le ton.</h2><p>Chaque intervention se prépare autour de l’objectif de votre événement et du niveau de familiarité de votre public avec le sujet.</p><a class="btn" href="contact.html?objet=Intervention">Inviter Coach OLOU</a></div><div><h3>1. Votre enjeu</h3><p>Quel message doit rester après l’intervention ? À qui s’adresse-t-elle ?</p><h3>2. Le bon format</h3><p>Conférence, panel, atelier pratique ou parcours de formation, en présentiel ou à distance.</p><h3>3. Une préparation commune</h3><p>Thème, durée, date, lieu, public et contraintes sont précisés ensemble.</p></div></div></section>'''+cta())
projects=[('strategie','Yirmea-Immo','Lancement & communication','Accompagnement du lancement officiel de Yirmea-Immo au Burkina Faso : coordination, communication, mobilisation des médias et production de contenus.','Relier la présentation de la solution, la rencontre avec les médias et la prise de parole de la marque.'),('strategie','ARCOP Burkina Faso','Communication institutionnelle','Audit digital, stratégie de communication, structuration de la présence sur les réseaux sociaux et couverture en direct.','Rendre l’information institutionnelle plus accessible et renforcer la présence digitale.'),('audiovisuel','Production & live streaming','OLOUSTREAM','Captation multicaméra, réalisation de podcasts, diffusion d’événements et création de contenus institutionnels.','Prolonger la portée d’un événement et valoriser les prises de parole.'),('formation','Activation professionnelle','Coaching & formation','Accompagnement des talents et des professionnels : connaissance de soi, clarification des priorités et construction d’un projet.','Relier les aspirations à des actions concrètes et à un suivi des progrès.')]
